export const MAGNIT_MOSCOW_STORES = Object.freeze(STORES.map((store) => Object.freeze(store)));
export const MAGNIT_MOSCOW_DIRECTORY_SOURCE = Object.freeze({
  url: "https://magnit.ru/shops",
  checkedAt: "2026-10-05T07:10:04.764Z",
  resolved: 491,
  unresolved: 6
});

export function resolveMagnitMoscowStore({ shopCode, address } = {}) {
  if (typeof shopCode !== "string" || !/^\d{4,12}$/u.test(shopCode)) return null;
  const store = MAGNIT_MOSCOW_STORES.find((entry) => entry.shopCode === shopCode);
  if (!store || store.status !== "resolved") return null;
  if (typeof address === "string" && address.trim() !== store.address) return null;
  return store;
}

